import type { CSSProperties } from 'react'
import raw from '@/public/lab/parts.json'

// The lab drawing set's data. public/lab/ is generated by the lab repo's `make showcase`; never edit it here.
// No fs: the viewer (a client component) imports this file too.

export type Box = [number, number, number, number]
export type Kind = 'device' | 'guest' | 'vlan' | 'area'
export type Part = { kind: Kind; label: string; planned: boolean; on: Record<string, Box[]> }
export type Sheet = { n: number; key: string; name: string; title: string; light: string; dark: string }
type Theme = { paper: string; ink: string; ink2: string; hl: string; hlop: number }
export type LabData = {
  schema: number
  rev: string
  w: number
  h: number
  sheets: Sheet[]
  palette: { light: Theme; dark: Theme }
  parts: Record<string, Part>
}

const SCHEMA = 1
const PAD = 40
const MIN_W = 560
const MIN_ASPECT = 1
const MAX_ASPECT = 2.4
const SOFT_MAX_W = 920 // owner, 2026-11-20: detail B of sheet 3 is 912 wide with its own labels
const OUTSET = 8

export const lab = raw as unknown as LabData

if (lab.schema !== SCHEMA) {
  throw new Error(`parts.json schema ${lab.schema}: this site understands ${SCHEMA}. Update lib/lab.ts.`)
}

const KIND_ORDER: Kind[] = ['device', 'guest', 'vlan', 'area']
const sheetKeys = () => lab.sheets.map((s) => s.key).join(', ')

export function sheetOf(key: string | undefined): Sheet {
  if (!key) {
    throw new Error(
      `LabSheet: 'sheet' is missing. Use one of: ${sheetKeys()}. MDX drops {...} values, so use a plain string.`,
    )
  }
  const sheet = lab.sheets.find((s) => s.key === key)
  if (!sheet) throw new Error(`LabSheet: no sheet '${key}'. Use one of: ${sheetKeys()}.`)
  return sheet
}

/** The part ids a figure lights: [] for the whole sheet. Throws at build time on a missing or unknown id. */
export function resolveFocus(sheet: Sheet, focus: string | undefined): string[] {
  if (!focus || !focus.trim()) {
    throw new Error(
      `LabSheet: 'focus' is missing. Write focus="sheet" for the whole sheet, or focus="id id" with part ids. ` +
        'MDX drops {...} values, so use a plain string.',
    )
  }
  if (focus.trim() === 'sheet') return []
  const ids = focus.trim().split(/\s+/)
  for (const id of ids) {
    const on = lab.parts[id]?.on
    if (!on?.[sheet.key]) {
      const elsewhere = on ? ` It is on: ${Object.keys(on).join(', ')}.` : ''
      throw new Error(
        `LabSheet: no part '${id}' on sheet '${sheet.key}' (REV ${lab.rev}).${elsewhere} The ids are in public/lab/parts.json.`,
      )
    }
  }
  return ids
}

export function boxesOf(sheetKey: string, ids: string[]): Box[] {
  return ids.flatMap((id) => lab.parts[id]?.on[sheetKey] ?? [])
}

/** The detail an embed shows: the lit boxes plus padding, at least MIN_W wide, aspect kept, inside the sheet. */
export function cropFor(sheet: Sheet, ids: string[]): Box {
  if (ids.length === 0) return [0, 0, lab.w, lab.h]
  const boxes = boxesOf(sheet.key, ids)
  const x0 = Math.min(...boxes.map((b) => b[0])) - PAD
  const y0 = Math.min(...boxes.map((b) => b[1])) - PAD
  const x1 = Math.max(...boxes.map((b) => b[0] + b[2])) + PAD
  const y1 = Math.max(...boxes.map((b) => b[1] + b[3])) + PAD
  const cx = (x0 + x1) / 2
  const cy = (y0 + y1) / 2
  let w = Math.max(x1 - x0, MIN_W)
  let h = y1 - y0
  if (w / h > MAX_ASPECT) h = w / MAX_ASPECT
  if (w / h < MIN_ASPECT) w = h * MIN_ASPECT
  w = Math.min(w, lab.w)
  h = Math.min(h, lab.h)
  const x = Math.min(Math.max(cx - w / 2, 0), lab.w - w)
  const y = Math.min(Math.max(cy - h / 2, 0), lab.h - h)
  const crop: Box = [Math.round(x), Math.round(y), Math.round(w), Math.round(h)]
  if (crop[2] > SOFT_MAX_W) {
    console.warn(
      `LabSheet: the detail of ${ids.join(' ')} is ${crop[2]} px wide; its text will be small in the 700 px column. ` +
        'Choose a smaller part.',
    )
  }
  return crop
}

/** One boundary per group of touching boxes: grow each by OUTSET, then join any two that touch until none do. */
export function groupBoxes(boxes: Box[]): Box[] {
  const rs = boxes.map(([x, y, w, h]) => [x - OUTSET, y - OUTSET, x + w + OUTSET, y + h + OUTSET])
  let joined = true
  while (joined) {
    joined = false
    for (let i = 0; i < rs.length && !joined; i++) {
      for (let j = i + 1; j < rs.length; j++) {
        const [a, b] = [rs[i], rs[j]]
        if (a[0] <= b[2] && b[0] <= a[2] && a[1] <= b[3] && b[1] <= a[3]) {
          rs[i] = [Math.min(a[0], b[0]), Math.min(a[1], b[1]), Math.max(a[2], b[2]), Math.max(a[3], b[3])]
          rs.splice(j, 1)
          joined = true
          break
        }
      }
    }
  }
  return rs.map(([x0, y0, x1, y1]) => [x0, y0, x1 - x0, y1 - y0])
}

/** The parts drawn on a sheet: devices, guests, VLANs, then areas, each by label. */
export function partsOn(sheetKey: string): [string, Part][] {
  return Object.entries(lab.parts)
    .filter(([, p]) => p.on[sheetKey])
    .sort(([, a], [, b]) => KIND_ORDER.indexOf(a.kind) - KIND_ORDER.indexOf(b.kind) || a.label.localeCompare(b.label))
}

function listOf(items: string[]): string {
  return items.length < 2 ? items.join('') : `${items.slice(0, -1).join(', ')} and ${items[items.length - 1]}`
}

export function altFor(sheet: Sheet, ids: string[]): string {
  const what = ids.length ? listOf(ids.map((id) => lab.parts[id].label)) : sheet.title.toLowerCase()
  return `Sheet ${sheet.n} (${sheet.key}) of the homelab drawing set: ${what}.`
}

// The sheet's own colours, one source (PALETTE in the lab's generator); app/globals.css maps them to the theme.
const { light, dark } = lab.palette
export const labVars = {
  '--lab-paper-l': light.paper,
  '--lab-ink-l': light.ink,
  '--lab-ink2-l': light.ink2,
  '--lab-hl-l': light.hl,
  '--lab-hlop-l': String(light.hlop),
  '--lab-paper-d': dark.paper,
  '--lab-ink-d': dark.ink,
  '--lab-ink2-d': dark.ink2,
  '--lab-hl-d': dark.hl,
  '--lab-hlop-d': String(dark.hlop),
} as CSSProperties
